(6643756, 992534, 86447, '<td valign="top">Oh!  I love this.    Simple architecture!   It''s very emotive.<br/> <br/> <br/>(I''m commenting only, not voting)</td>', 'Oh!  I love this.    Simple architecture!   It''s very emotive.  (I''m commenting only, not voting)', '2012-01-13 00:24:29.000000', NULL, 1),
(6643757, 992467, 86447, '<td valign="top">I love those shadows.</td>', 'I love those shadows.', '2012-01-13 00:24:50.000000', NULL, 1),
(6643758, 992560, 142483, '<td valign="top">Wow, this fits the challenge description very well in my opinion. It has such a dramatic feel, it''s kind of scary. It reminds me of the music during a suspensful part of a film, when the object jumps out or appears and the music bangs loudly to make you jump... haha hopefully that makes sense! Very well done</td>', 'Wow, this fits the challenge description very well in my opinion. It has such a dramatic feel, it''s kind of scary. It reminds me of the music during a suspensful part of a film, when the object jumps out or appears and the music bangs loudly to make you jump... haha hopefully that makes sense! Very well done', '2012-01-13 00:24:50.000000', NULL, 1),
(6643759, 992502, 96751, '<td valign="top">I don''t know what you did with the pp''ing, but I love it!!  Very groovy vibe, and love the retro reflections in the uber modern structure.  Great work.</td>', 'I don''t know what you did with the pp''ing, but I love it!!  Very groovy vibe, and love the retro reflections in the uber modern structure.  Great work.', '2012-01-13 00:24:51.000000', NULL, 1),
