(6643763, 992584, 96751, '<td valign="top">Fascinating.  The structures are actually the negative space of this image, which reveals a slender silhouette of sky and building</td>', 'Fascinating.  The structures are actually the negative space of this image, which reveals a slender silhouette of sky and building', '2012-01-13 00:25:38.000000', NULL, 1),
(6643764, 991897, 142483, '<td valign="top">I love the dramatic feel, it is very solemn and somber</td>', 'I love the dramatic feel, it is very solemn and somber', '2012-01-13 00:25:40.000000', NULL, 1),
