(6644368, 992481, 117804, '<td valign="top">Nice one. Could have been better cropped in a different way (without the upper part may be)</td>', 'Nice one. Could have been better cropped in a different way (without the upper part may be)', '2012-01-13 14:45:59.000000', NULL, 1),
