(6646976, 992513, 69446, '<td valign="top">Lovely tones... 7 from me. Well done.</td>', 'Lovely tones... 7 from me. Well done.', '2012-01-16 17:03:23.000000', NULL, 1),
(6646978, 992543, 69446, '<td valign="top">Lovely angle and composition... the building is a little soft though. 7 from me. Well done.</td>', 'Lovely angle and composition... the building is a little soft though. 7 from me. Well done.', '2012-01-16 17:04:00.000000', NULL, 1),
(6646984, 992477, 69446, '<td valign="top">Very interesting image, it made me pause to take it in. Lovely tonality. Silver Efex Pro? Either way, my pick of the challenge. 9 from me.</td>', 'Very interesting image, it made me pause to take it in. Lovely tonality. Silver Efex Pro? Either way, my pick of the challenge. 9 from me.', '2012-01-16 17:06:06.000000', NULL, 1),
(6646986, 992584, 69446, '<td valign="top">Nice composition, the caption fits the image perfectly and guides the viewer in interesting directions. Well done, 8 from me.</td>', 'Nice composition, the caption fits the image perfectly and guides the viewer in interesting directions. Well done, 8 from me.', '2012-01-16 17:07:14.000000', NULL, 1),
(6647320, 992069, 73452, '<td valign="top">incredible color, lovely lines that lead my eye through the image. nice and sharp. very well done.</td>', 'incredible color, lovely lines that lead my eye through the image. nice and sharp. very well done.', '2012-01-17 00:00:48.000000', NULL, 1),
(6647359, 992481, 61396, '<td valign="top">repetition works great. I''m guessing these guys didn''t make it all the way up, so you have missed an even higher emotional impact by composing them differently and using stronger motion blur. (not voting)</td>', 'repetition works great. I''m guessing these guys didn''t make it all the way up, so you have missed an even higher emotional impact by composing them differently and using stronger motion blur. (not voting)', '2012-01-17 02:20:26.000000', NULL, 1),
(6647362, 991965, 61396, '<td valign="top">it is well received here. (not voting).<br/> <br/>p.s. just a suggestion - ignore the no trespassing sign and compose some footstep impressions on the snow.</td>', 'it is well received here. (not voting). p.s. just a suggestion - ignore the no trespassing sign and compose some footstep impressions on the snow.', '2012-01-17 02:30:27.000000', NULL, 1),
(6647646, 991917, 43774, '<td valign="top">Well done. Would love to see this building myself.</td>', 'Well done. Would love to see this building myself.', '2012-01-17 13:28:32.000000', NULL, 1),
(6647647, 992082, 43774, '<td valign="top">Perfect for this challenge, impressive.</td>', 'Perfect for this challenge, impressive.', '2012-01-17 13:28:49.000000', NULL, 1),
(6647648, 992069, 43774, '<td valign="top">Reminds me of the pyramids, nice.</td>', 'Reminds me of the pyramids, nice.', '2012-01-17 13:29:06.000000', NULL, 1),
(6647755, 992534, 69446, '<td valign="top">Lovely. You can''t go wrong with cracked paint :-) 8 from me.</td>', 'Lovely. You can''t go wrong with cracked paint :-) 8 from me.', '2012-01-17 17:17:08.000000', NULL, 1),
(6647757, 992467, 69446, '<td valign="top">Lovely tones and good use of thirds... it''s a pity the top third of the picture is less interesting. Still a very nice photo. 7 from me.</td>', 'Lovely tones and good use of thirds... it''s a pity the top third of the picture is less interesting. Still a very nice photo. 7 from me.', '2012-01-17 17:19:41.000000', NULL, 1),
(6647759, 992356, 69446, '<td valign="top">Ahh Calatrava... he''s my favourite architect! Thanks for the capture, nice shot. 7 from me.</td>', 'Ahh Calatrava... he''s my favourite architect! Thanks for the capture, nice shot. 7 from me.', '2012-01-17 17:20:34.000000', NULL, 1),
(6647760, 992481, 69446, '<td valign="top">It''s bizarre but this photo makes me feel like I''m looking up, not down. Nice tone mapping. 7 from me.</td>', 'It''s bizarre but this photo makes me feel like I''m looking up, not down. Nice tone mapping. 7 from me.', '2012-01-17 17:20:44.000000', NULL, 1),
(6647761, 992590, 69446, '<td valign="top">Lovely textures... you can''t go wrong with crackling paint! 7 from me.</td>', 'Lovely textures... you can''t go wrong with crackling paint! 7 from me.', '2012-01-17 17:21:19.000000', NULL, 1),
(6647762, 992195, 69446, '<td valign="top">You could have called this one "Lord Vader"... it just leaps right out at you! Good eye. 7 from me.</td>', 'You could have called this one "Lord Vader"... it just leaps right out at you! Good eye. 7 from me.', '2012-01-17 17:22:00.000000', NULL, 1),
(6647763, 992539, 69446, '<td valign="top">Love the diagonals... nice composition. Pity about the bright cloud right on the left edge, it''s a minor distraction. Good job. 7 from me.</td>', 'Love the diagonals... nice composition. Pity about the bright cloud right on the left edge, it''s a minor distraction. Good job. 7 from me.', '2012-01-17 17:22:12.000000', NULL, 1),
(6647935, 992082, 124982, '<td valign="top">Superbly processed, very nice! Absolutely love the details in all the shadows...very crisp!</td>', 'Superbly processed, very nice! Absolutely love the details in all the shadows...very crisp!', '2012-01-17 20:27:50.000000', NULL, 1),
(6647942, 992356, 124982, '<td valign="top">Beautiful structure, Santiago did good with this. While the lines and shadows are awesome, I find the monotone blue cast in this a little underwhelming. I wonder if a B&amp;W version of this would''ve made it pop? Really draw the details of the the highlights and shadows out. Very nice, nonetheless!!</td>', 'Beautiful structure, Santiago did good with this. While the lines and shadows are awesome, I find the monotone blue cast in this a little underwhelming. I wonder if a B&W version of this would''ve made it pop? Really draw the details of the the highlights and shadows out. Very nice, nonetheless!!', '2012-01-17 20:29:41.000000', NULL, 1),
(6647962, 992478, 49018, '<td valign="top">Wondeful sense of movement, as from a train. The figure obviously adds a lot. 9</td>', 'Wondeful sense of movement, as from a train. The figure obviously adds a lot. 9', '2012-01-17 21:10:02.000000', NULL, 1),
